  const ITEM_SET = {};
  Object.keys(SET_ITEMS).forEach(function (s) { SET_ITEMS[s].forEach(function (n) { ITEM_SET[n] = s; }); });

  /* ---------------- 技能等级（SL 口径，用于技能要求） ---------------- */
  function classify(name, skillMap, itemSet, prof) {
    if (skillMap[name]) return "skill";
    if (itemSet.has(name)) return "equip";
    if (/雕像$/.test(name)) return "statue";
    if (prof && name === prof) return "cls";
    return "set";
  }

  function computeSkills(rows, ctx, exclude) {
    function isExcluded(name) {
      if (!exclude) return false;
      if (typeof exclude === "string") return name === exclude;
      if (typeof exclude.has === "function") return exclude.has(name);
      return false;
    }
    const skillMap = {};
    rows.forEach(function (r) { skillMap[r.name] = r; });
    const itemSet = ctx.items;
    const heroLevel = ctx.level || 1;
    const prof = ctx.prof || "";

    const pres = rows.map(function (r) {
      if (r.scriptOnly) return null;
      const base = r.base || 0;
      let eqPos = 0, eqNeg = 0, eqPct = 1, setFlat = 0, setPct = 1, stFlat = 0, clFlat = 0;
      const tips = (r.tips || []).filter(function (tip) {
        return tip.name && tip.expr && !/\(a\)/i.test(tip.expr);
      });
      const eqByName = new Map();
      tips.forEach(function (tip) {
        if (isExcluded(tip.name)) return;
        if (classify(tip.name, skillMap, itemSet, prof) !== "equip") return;
        const v = evalExprParts(tip.expr, base, heroLevel);
        let g = eqByName.get(tip.name);
        if (!g) { g = { flat: 0, pct: 1 }; eqByName.set(tip.name, g); }
        g.flat += v.fixed + v.skill + v.hero;
        g.pct *= v.pct;
      });
      eqByName.forEach(function (g) {
        const own = g.flat > 0 ? g.flat * g.pct : g.flat;
        if (own >= 0) eqPos += own; else eqNeg += own;
        eqPct *= g.pct;
      });
      const eqPosCapped = Math.min(eqPos, 2 * base);
      const eqNet = eqPosCapped + eqNeg;
      const eqGain = Math.min(eqNet, base);
      const base2 = Math.min(base * eqPct + eqGain, 2 * base);

      const skTips = [];
      tips.forEach(function (tip) {
        if (isExcluded(tip.name)) return;
        const kind = classify(tip.name, skillMap, itemSet, prof);
        if (kind === "equip") return;
        if (kind === "skill") {
          const selfBuff = (tip.name === r.name && /技能等级/.test(tip.expr));
          skTips.push({ name: tip.name, expr: tip.expr, selfBuff: selfBuff });
          return;
        }
        const v = evalExprParts(tip.expr, base, heroLevel);
        const flat = v.fixed + v.skill + v.hero;
        if (kind === "set") { setFlat += flat; setPct *= v.pct; }
        else if (kind === "statue") stFlat += flat;
        else if (kind === "cls") clFlat += flat;
      });

      return {
        r: r, base: base, base2: base2,
        setFlat: setFlat, setPct: setPct, setApplied: base2 * setPct,
        stFlat: stFlat, clFlat: clFlat, skTips: skTips
      };
    }).filter(Boolean);

    function parts(pre, levels) {
      let skSkill = 0, skHero = 0, skFixed = 0;
      pre.skTips.forEach(function (t) {
        const srcRow = skillMap[t.name];
        let srcLv;
        if (t.selfBuff) srcLv = pre.base2;
        else if (levels[t.name] != null) srcLv = levels[t.name];
        else srcLv = srcRow ? (srcRow.game != null ? srcRow.game : srcRow.base) : 0;
        const vp = evalExprParts(t.expr, srcLv, heroLevel);
        skSkill += vp.skill; skHero += vp.hero; skFixed += vp.fixed;
      });
      return { skSkill: skSkill, skHero: skHero, skFixed: skFixed,
        skFlat: Math.floor(skSkill) + skHero + skFixed };
    }

    // 第一轮用页面显示值作种子，之后每轮都用算出的值覆盖：
    // 这样“卸下某件装备”后，依赖该技能等级的其它技能也会跟着重算。
    const displayLevels = {};
    pres.forEach(function (p) { if (p.r.game != null) displayLevels[p.r.name] = p.r.game; });
    let displayVals = {};
    for (let it = 0; it < 4; it++) {
      pres.forEach(function (p) {
        const sk = parts(p, displayLevels);
        const display = Math.max(0, Math.floor(Math.min(p.setApplied, 2 * p.base) + p.setFlat + sk.skFlat + p.stFlat + p.clFlat));
        displayVals[p.r.name] = display;
        displayLevels[p.r.name] = display;
      });
    }
    const actualLevels = {};
    pres.forEach(function (p) { actualLevels[p.r.name] = displayLevels[p.r.name]; });
    let actualVals = {};
    for (let it = 0; it < 4; it++) {
      let changed = false;
      pres.forEach(function (p) {
        const sk = parts(p, actualLevels);
        const actual = Math.max(0, Math.floor(p.setApplied + p.setFlat + sk.skFlat + p.stFlat + p.clFlat));
        actualVals[p.r.name] = actual;
        if (actualLevels[p.r.name] !== actual) { actualLevels[p.r.name] = actual; changed = true; }
      });
      if (!changed) break;
    }

    const out = {};
    rows.forEach(function (r) {
      if (r.scriptOnly) {
        out[r.name] = {
          base: r.base || 0,
          display: r.game != null ? r.game : (r.base || 0),
          actual: r.game != null ? r.game : (r.base || 0),
          game: r.game, scriptOnly: true
        };
        return;
      }
      out[r.name] = {
        base: r.base || 0,
        display: displayVals[r.name] != null ? displayVals[r.name] : (r.base || 0),
        actual: actualVals[r.name] != null ? actualVals[r.name] : (r.base || 0),
        game: r.game
      };
    });
    return out;
  }

  /* ---------------- 解析 ---------------- */
  function parseGear(doc) {
    const list = [];
    doc.querySelectorAll('select[name^="LocationEquip["]').forEach(function (sel) {
      const m = sel.name.match(/^LocationEquip\[(\w+)\]\[(\d+)\]$/);
      if (!m) return;
      const opt = sel.options[sel.selectedIndex];
      if (!opt) return;
      const name = normName(opt.textContent).replace(/\s*!\s*$/, "").trim();
      if (!name) return;
      const hid = (location.search.match(/session_hero_id=(\d+)/) || [])[1] || "";
      let iid = "";
      const key = "LocationDefault[" + m[1] + "][" + m[2] + "]";
      const inputs = doc.querySelectorAll('input[name^="LocationDefault["]');
      for (let i = 0; i < inputs.length; i++) {
        if (inputs[i].name.indexOf(key) === 0) { iid = inputs[i].value; break; }
      }
      list.push({ slot: m[1], idx: m[2], name: name, iid: iid, sel: sel });
    });
    return list;
  }

  function parseAttrs(html) {
    const doc = new DOMParser().parseFromString(html, "text/html");
    const lvEl = doc.querySelector('input[name="stufe"]');
    const level = lvEl ? (parseInt(lvEl.value, 10) || 1) : 1;
    const attrs = {};
    doc.querySelectorAll("tr").forEach(function (tr) {
      const firstTd = tr.querySelector("td");
      if (!firstTd) return;
      // 无任何加成的属性行没有 tooltip，标签直接是纯文本；必须先按名字识别，不能靠 tooltip 找行
      const name = normName(firstTd.textContent);
      if (ATTR_ORDER.indexOf(name) < 0) return;
      const vm = tr.innerHTML.match(/>\s*(-?\d+)\s*<span class="effective_value">(?:\[(-?\d+)\])?<\/span>/);
      if (!vm) return;
      const raw = parseInt(vm[1], 10);
      // 没有黄字（空 effective_value）说明最终值等于原始值：加成全无或互相抵消
      const eff = vm[2] != null ? parseInt(vm[2], 10) : raw;
      const span = tr.querySelector('span[onmouseover*="wodToolTip"]');
      const tipRaw = span ? (span.getAttribute("onmouseover") || "") : "";
      const tm = tipRaw.match(/wodToolTip\(this,\s*'([\s\S]*?)'\s*\)/);
      let entries = [];
      if (tm) {
        const tip = decodeEntities(tm[1]);
        entries = tip.split(/<br\s*\/?>/i).map(function (part) {
          const txt = normName(part);
          const mm = txt.match(/^(.*?)\s*\(([^()]*)\)$/);
          return mm ? { src: mm[1].trim(), expr: mm[2].trim() } : null;
        }).filter(Boolean);
      }
      attrs[name] = { raw: raw, eff: eff, entries: entries };
    });
    // 职业/种族：属性页用 hidden input 存，装备页要拿它区分“职业加成”和普通来源
    const kn = doc.querySelector('input[name="klasse_name"]');
    const rn = doc.querySelector('input[name="rasse_name"]');
    return {
      level: level, attrs: attrs,
      prof: kn ? kn.value : "",
      race: rn ? rn.value : ""
    };
  }

  function parseItemPage(html, name) {
    const doc = new DOMParser().parseFromString(html, "text/html");
    let reqText = "", pos = "", category = "";
    let pocketBonus = 0;   // 容器提供的「#口袋位」加成，用于口袋容量连锁
    const categories = [];
    const tds = doc.querySelectorAll("td");
    for (let i = 0; i < tds.length; i++) {
      const label = normName(tds[i].textContent);
      if (label === "装备要求" && tds[i + 1]) {
        reqText = tds[i + 1].innerHTML.split(/<br\s*\/?>/i).map(function (x) { return normName(x); }).filter(Boolean).join("\n");
      } else if (label === "装备位置" && tds[i + 1]) {
        pos = normName(tds[i + 1].textContent);
      } else if (label.replace(/\s+/g, "") === "#口袋位" && tds[i + 1]) {
        const pm = tds[i + 1].textContent.match(/[+-]?\d+/);
        if (pm) pocketBonus = parseInt(pm[0], 10);
      } else if (label.indexOf("物品类别") === 0 && tds[i + 1]) {
        const cell = tds[i + 1];
        category = normName(cell.textContent);
        categories.length = 0;
        cell.querySelectorAll('a[href*="物品类别_-_"]').forEach(function (a) {
          const t = normName(a.textContent);
          if (t && categories.indexOf(t) < 0) categories.push(t);
        });
        if (!categories.length) {
          // 兜底：按 <br> 拆行，去掉 (+0/+0) 与“只能装备一个”的说明
          String(cell.innerHTML).split(/<br\s*\/?>/i).forEach(function (x) {
            const t = normName(x)
              .replace(/\([+\-]?\d+\/[+\-]?\d+\)/g, "")
              .replace(/\(您只能装备[^)]*\)/g, "")
              .trim();
            if (t && categories.indexOf(t) < 0) categories.push(t);
          });
        }
      }
    }
    return { schema: ITEM_SCHEMA, name: name, pos: pos, category: category, categories: categories, pocketBonus: pocketBonus, reqText: reqText, reqs: parseReqs(reqText) };
  }

  function parseReqs(text) {
    const out = [];
    String(text || "").split("\n").forEach(function (line) {
      const s = line.replace(/\s+/g, "");
      if (!s) return;
      if (s.indexOf("荣誉") >= 0) return;            // 荣誉/联盟荣誉不参与
      if (/至多可以装备一件/.test(s)) return;          // 类别独占，卸下只会变少，不会触发
      if (/无任何需求/.test(s)) return;
      // 物品类别件数要求（如“英雄必须装备至少一件舞蹈用品物品”“英雄必须装备领舞用香料类别的至少4件物品”）：
      // 卸下同类别装备会让“已装备件数”下降，可能连带其他装备脱落。
      const cnNum = { "一": 1, "两": 2, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9, "十": 10 };
      let cm = s.match(/^英雄必须装备至少([一二两三四五六七八九十]|\d+)件(.+?)物品$/);
      if (cm) {
        out.push({ kind: "catcount", name: cm[2].replace(/类别的?$/, ""), op: "atleast", n: cnNum[cm[1]] || parseInt(cm[1], 10) });
        return;
      }
      cm = s.match(/^英雄必须装备(.+?)(?:类别)?的?至少([一二两三四五六七八九十]|\d+)件物品$/);
      if (cm) {
        out.push({ kind: "catcount", name: cm[1].replace(/类别的?$/, ""), op: "atleast", n: cnNum[cm[2]] || parseInt(cm[2], 10) });
        return;
      }
      const m = s.match(/^(.*?)(至少为|最高到)(-?\d+)/);
      if (!m) return;
      let nm = m[1].trim(), op = m[2] === "最高到" ? "atmost" : "atleast", n = parseInt(m[3], 10);
      let raw = false;
      if (/\(原始值\)$/.test(nm)) { raw = true; nm = nm.replace(/\(原始值\)$/, ""); }
      if (nm === "等级") out.push({ kind: "level", name: "等级", op: op, n: n });
      else if (ATTR_ORDER.indexOf(nm) >= 0) out.push({ kind: "attr", name: nm, op: op, n: n, raw: raw });
      else out.push({ kind: "skill", name: nm, op: op, n: n });
    });
    return out;
  }

  /* ---------------- 模型 ---------------- */
  function collectSkillRows(doc) {
    const rows = [];
    doc.querySelectorAll('div[id^="skill_rang_"]').forEach(function (div) {
      let tr = div.closest("tr");
      while (tr && !tr.querySelector('a[href*="skill.php?name="]')) tr = tr.parentElement ? tr.parentElement.closest("tr") : null;
      if (!tr) return;
      const a = tr.querySelector('a[href*="skill.php?name="]');
      if (!a) return;
      const name = normName(a.textContent);
      if (!name) return;
      const baseTxt = (div.textContent || "").replace(/[^\d-]/g, "");
      const base = /^-?\d+$/.test(baseTxt) ? parseInt(baseTxt, 10) : 0;
      const effEl = tr.querySelector('span[id^="skill_eff_rang_"]');
      let game = null;
      if (effEl) {
        const t = (effEl.textContent || "").replace(/[^\d-]/g, "");
        if (/^-?\d+$/.test(t)) game = parseInt(t, 10);
      }
      const om = a.getAttribute("onmouseover") || "";
      rows.push({
        id: div.id.replace("skill_rang_", ""), name: name, base: base, game: game, tips: parseTips(om),
        row: tr, nameAnchor: a, anchor: div
      });
    });
    return rows;
  }

  // 技能页里自带一份 JS 数据：skills["id"]["name"|"rang"|"eff_rang"]。
  // 当页面结构变化/只渲染了部分技能时，用它兜底（eff_rang 就是游戏显示的有效等级）。
  function parseSkillScript(html) {
    const h = String(html || "");
    const names = {}, base = {}, eff = {};
    let m;
    const reN = /skills\["(\d+)"\]\["name"\]\s*=\s*"([^"]*)"/g;
    while ((m = reN.exec(h))) names[m[1]] = m[2];
    const reB = /skills\["(\d+)"\]\["rang"\]\s*=\s*(-?\d+)/g;
    while ((m = reB.exec(h))) base[m[1]] = parseInt(m[2], 10);
    const reE = /skills\["(\d+)"\]\["eff_rang"\]\s*=\s*(-?\d+)/g;
    while ((m = reE.exec(h))) eff[m[1]] = parseInt(m[2], 10);
    const out = [];
    Object.keys(names).forEach(function (id) {
      const n = normName(html_unescape(names[id]));
      if (!n) return;
      const g = eff[id] != null ? eff[id] : null;
      let b = base[id] || 0;
      // 只收“有效等级 > 0”的技能：部分页面会把未学技能的 rang 写成技能 ID/占位值
      // （如 1005、1007），而 eff_rang 为 0；这类行绝不能当技能等级参与判定。
      if (!(g > 0)) return;
      // 已学但 rang 仍是占位值时，用 eff_rang 兜底，避免出现 1005 级
      if (b >= 100 || String(b) === String(id)) b = g;
      out.push({ id: id, name: n, base: b, game: g, tips: [], scriptOnly: true });
    });
    return out;
  }

  function html_unescape(s) {
    const ta = document.createElement("textarea");
    ta.innerHTML = String(s || "");
    return ta.value;
  }

  function parseTips(raw) {
    const out = [];
    const m = String(raw || "").match(/wodToolTip\(this,\s*'([\s\S]*?)'\s*\)/);
    if (!m) return out;
    const tip = decodeEntities(m[1]);
    tip.split(/<br\s*\/?>/i).forEach(function (part) {
      const txt = normName(part);
      const mm = txt.match(/^(.*?)\s*\(([^()]*)\)$/);
      if (mm) out.push({ name: mm[1].trim(), expr: mm[2].trim() });
    });
    return out;
  }

  function setTierRows(setName, count) {
    const tiers = SET_ATTR[setName];
    if (!tiers) return null;
    let best = 0;
    Object.keys(tiers).forEach(function (k) { const n = parseInt(k, 10); if (n <= count && n > best) best = n; });
    return best ? tiers[String(best)] : null;
  }

  function setAttrRows(setName, count, attr) {
    const rows = setTierRows(setName, count);
    if (!rows) return [];
    return rows.filter(function (r) { return r[0] === attr; });
  }

  function setCountsOf(items) {
    const counts = {};
    items.forEach(function (n) {
      const s = ITEM_SET[n];
      if (s) counts[s] = (counts[s] || 0) + 1;
    });
    return counts;
  }

  function buildBase(attrData, skillRows, gearItems, itemInfos, prof) {
    const names = gearItems.map(function (g) { return g.name; });
    const items = new Set(names);
    const setCounts = setCountsOf(items);
    const skillVals = computeSkills(skillRows, { items: items, level: attrData.level, prof: prof }, new Set());

    const state = {
      level: attrData.level,
      attrs: attrData.attrs,
      items: items,
      allItems: new Set(names),
      setCounts: setCounts,
      skillVals: skillVals,
      itemInfos: itemInfos,
      attrAdj: {}
    };

    // 校准：模型值与页面实际值的差，按属性固定补偿（保证基线完全一致）
    ATTR_ORDER.forEach(function (a) {
      if (!state.attrs[a]) return;
      const model = attrValue(state, a);
      state.attrAdj[a] = state.attrs[a].eff - model;   // 正常为 0（页面 = floor(模型)），异常时兜底
    });
    return state;
  }

  function attrSourceKind(src, state) {
    // 用“全部已装备过的装备名”判定来源类型：被卸下的装备仍算装备，不能滑到 other 里继续生效
    if (state.allItems && state.allItems.has(src)) return "item";
    if (state.setCounts[src]) return "set";
    if (state.skillVals[src]) return "skill";
    return "other";
  }

  function attrValue(state, attr) {
    const info = state.attrs[attr];
    if (!info) return 0;
    const raw = info.raw;
    let v = raw;
    (info.entries || []).forEach(function (e) {
      const kind = attrSourceKind(e.src, state);
      if (kind === "set") return;                     // 套装按分档单独算
      if (kind === "item" && !state.items.has(e.src)) return;
      const lv = kind === "skill" && state.skillVals[e.src] ? state.skillVals[e.src].display : 0;
      const val = evalAttrEntry(e.expr, raw, state.level, lv);
      v += val.flat + val.pct * raw;
    });
    Object.keys(state.setCounts).forEach(function (s) {
      setAttrRows(s, state.setCounts[s], attr).forEach(function (row) {
        const val = evalAttrEntry(row[1], raw, state.level, 0);
        v += val.flat + val.pct * raw;
      });
    });
    // 游戏对属性只做一次取整（向下）
    return Math.floor(v + (state.attrAdj[attr] || 0) + 1e-9);
  }

  function itemAttrContribution(state, itemName, attr) {
    const info = state.attrs[attr];
    if (!info) return 0;
    let v = 0;
    (info.entries || []).forEach(function (e) {
      if (e.src !== itemName) return;
      const val = evalAttrEntry(e.expr, info.raw, state.level, 0);
      v += val.flat + val.pct * info.raw;
    });
    return v;
  }

  // 自洽判定专用：只算该装备对该属性提供的「基础值」（固定/折算），不含裸百分比放大。
  // 与模拟器 _item_base_contribution 口径一致：排除自身加成时不把百分比乘算后的值扣掉。
  function itemAttrBaseAddon(state, itemName, attr) {
    const info = state.attrs[attr];
    if (!info) return 0;
    let v = 0;
    (info.entries || []).forEach(function (e) {
      if (e.src !== itemName) return;
      v += evalAttrEntry(e.expr, info.raw, state.level, 0).flat;
    });
    return v;
  }

  function cloneState(base, removed, rowsOverride) {
    const items = new Set();
    base.items.forEach(function (n) { if (!removed.has(n)) items.add(n); });
    const st = {
      level: base.level,
      attrs: base.attrs,
      items: items,
      allItems: base.allItems,
      setCounts: setCountsOf(items),
      skillVals: null,
      itemInfos: base.itemInfos,
      attrAdj: base.attrAdj,
      skillRows: rowsOverride || base.skillRows,
      prof: base.prof
    };
    st.skillVals = computeSkills(st.skillRows, { items: items, level: st.level, prof: st.prof }, removed);
    return st;
  }

  function countCategory(state, cat) {
    let n = 0;
    state.items.forEach(function (name) {
      const inf = state.itemInfos[name];
      if (!inf || !inf.categories) return;
      const key = catKey(cat);
      if (inf.categories.some(function (c) { return catKey(c) === key; })) n++;
    });
    return n;
  }

  // 技能名归一化：全角/半角冒号与括号、空格差异都视为同一技能
  function skillKey(s) {
    return String(s || "").replace(/[\s\u00a0]+/g, "")
      .replace(/[：:]/g, ":").replace(/[（）()]/g, "").toLowerCase();
  }

  // 技能页可能因为结构变化/会话问题漏掉某些技能；找不到时不要按 0 处理（会误报大量脱落），
  // 而是记一笔“未能验证”，由界面提示。
  const SKILL_INDEX = new WeakMap();
  function skillValOf(state, name) {
    const vals = state.skillVals || {};
    if (vals[name]) return vals[name];
    let idx = SKILL_INDEX.get(vals);
    if (!idx) {
      idx = {};
      Object.keys(vals).forEach(function (k) { idx[skillKey(k)] = vals[k]; });
      SKILL_INDEX.set(vals, idx);
    }
    return idx[skillKey(name)] || null;
  }

  const SKILL_ROW_INDEX = new WeakMap();
  function skillRowOf(state, name) {
    const rows = state.skillRows || [];
    let idx = SKILL_ROW_INDEX.get(rows);
    if (!idx) {
      idx = {};
      rows.forEach(function (r) { idx[skillKey(r.name)] = r; });
      SKILL_ROW_INDEX.set(rows, idx);
    }
    return idx[skillKey(name)] || null;
  }

  // 自洽判定专用：该装备对某技能的「基础固定等级」贡献（±N、±N%×英雄等级、±N%×技能等级）。
  // 技能页 tips 里装备来源的等级加成会随卸下整件消失；这里只取加法部分，
  // 并按模拟器口径处理基础加点封顶：装备总加成超过基础时，超出部分不实际生效、不计入贡献。
  function itemSkillBaseAddon(state, itemName, skillName) {
    const row = skillRowOf(state, skillName);
    if (!row) return 0;
    const base = row.base || 0;
    const hero = state.level || 1;
    // 按来源分组：组内正数固定值吃本组百分比，与 computeSkills 的装备口径一致
    const groups = new Map();
    (row.tips || []).forEach(function (tip) {
      if (!tip.name || !tip.expr || /\(a\)/i.test(tip.expr)) return;
      if (!state.items || !state.items.has(tip.name)) return;
      const v = evalExprParts(tip.expr, base, hero);
      let g = groups.get(tip.name);
      if (!g) { g = { flat: 0, pct: 1 }; groups.set(tip.name, g); }
      g.flat += v.fixed + v.skill + v.hero;
      g.pct *= v.pct;
    });
    function base2Of(skipName) {
      let eqPos = 0, eqNeg = 0, eqPct = 1;
      groups.forEach(function (g, name) {
        if (skipName && name === skipName) return;
        const own = g.flat > 0 ? g.flat * g.pct : g.flat;
        if (own >= 0) eqPos += own; else eqNeg += own;
        eqPct *= g.pct;
      });
      const eqPosCapped = Math.min(eqPos, 2 * base);
      const eqGain = Math.min(eqPosCapped + eqNeg, base);
      return Math.min(base * eqPct + eqGain, 2 * base);
    }
    // 只扣「真正改变了整数等级」的部分：0.69 这种小数加成在 2.69→2.0 时并没有改变
    // 显示等级（游戏只按 floor 显示），硬减会把 2 判成 1.31<2，导致整页装备全红。
    const withIt = base2Of(null);
    const without = base2Of(itemName);
    return Math.max(0, Math.floor(withIt) - Math.floor(without));
  }

  function checkReqs(itemInfo, state, itemName) {
    if (!itemInfo || !itemInfo.reqs || !itemInfo.reqs.length) return [];
    const reasons = [];
    itemInfo.reqs.forEach(function (r) {
      if (r.kind === "level") {
        const v = state.level;
        if (r.op === "atleast" && v < r.n) reasons.push("等级 " + v + " < " + r.n);
        else if (r.op === "atmost" && v > r.n) reasons.push("等级 " + v + " > " + r.n);
        return;
      }
      if (r.kind === "catcount") {
        const cnt = countCategory(state, r.name);
        if (r.op === "atleast" && cnt < r.n) {
          reasons.push("需要「" + r.name + "」至少 " + r.n + " 件，卸下后只剩 " + cnt + " 件");
        } else if (r.op === "atmost" && cnt > r.n) {
          reasons.push("「" + r.name + "」最多 " + r.n + " 件，现在有 " + cnt + " 件");
        }
        return;
      }
      if (r.kind === "attr") {
        // 自洽：排除这件装备自身提供的基础加成/减益后再判断（原始值不受装备影响，直接取 raw）
        let v = r.raw ? (state.attrs[r.name] ? state.attrs[r.name].raw : 0) : attrValue(state, r.name);
        if (!r.raw && itemName) v -= itemAttrBaseAddon(state, itemName, r.name);
        if (r.op === "atleast" && v < r.n - 1e-9) {
          reasons.push(r.name + (r.raw ? "(原始值)" : "") + " " + fmtNum(v) + " < " + r.n);
        } else if (r.op === "atmost" && v > r.n + 1e-9) {
          reasons.push(r.name + (r.raw ? "(原始值)" : "") + " " + fmtNum(v) + " > " + r.n);
        }
        return;
      }
      // 技能
      const sv = skillValOf(state, r.name);
      if (!sv) {
        state.missingSkills = state.missingSkills || {};
        state.missingSkills[r.name] = 1;
        return;
      }
      // 自洽：扣掉这件装备自己对技能等级的基础折算，再看是否仍满足
      // 自洽：扣掉这件装备对自己的技能等级贡献（只扣真正影响整数等级的部分）
      const v = sv.display - (itemName ? itemSkillBaseAddon(state, itemName, r.name) : 0);
      if (r.op === "atleast" && v < r.n) reasons.push(r.name + " " + fmtNum(v) + " < " + r.n);
      else if (r.op === "atmost" && v > r.n) reasons.push(r.name + " " + fmtNum(v) + " > " + r.n);
    });
    return reasons;
  }

  function lowAttr(state) {
    for (let i = 0; i < ATTR_ORDER.length; i++) {
      const a = ATTR_ORDER[i];
      if (!state.attrs[a]) continue;
      const v = attrValue(state, a);
      if (v < 1 - 1e-9) return { attr: a, value: v };
    }
    return null;
  }

  function worstNegativeItem(state, attr) {
    let worst = null, worstVal = 0;
    state.items.forEach(function (n) {
      const c = itemAttrContribution(state, n, attr);
      if (c < worstVal - 1e-9) { worstVal = c; worst = n; }
    });
    return worst;
  }

  // 技能等级快照（阈值分析要比对不同白字下的显示等级）
  function skillDisplayMap(vals) {
    const out = {};
    Object.keys(vals || {}).forEach(function (n) { out[n] = vals[n].display; });
    return out;
  }

  // excludeName 为空时表示“不卸装备，只改技能行”（技能阈值分析用）
  function simulate(base, excludeName, rowsOverride, presetRemoved) {
    const removed = new Set(presetRemoved || []);
    if (excludeName) removed.add(excludeName);
    const state = cloneState(base, removed, rowsOverride);
    state.missingSkills = {};
    const drops = [];

    function isContainer(name) {
      const inf = base.itemInfos[name];
      // 仅 +1 口袋位的装备（烟斗/钱袋等）掉落后影响很小，不按容器处理；+2 及以上才警告并停止
      return !!(inf && inf.pocketBonus > 1);
    }
    function setNotesNow() {
      const notes = [];
      Object.keys(base.setCounts).forEach(function (st) {
        const after = state.setCounts[st] || 0;
        if (after < base.setCounts[st]) notes.push(st + " " + base.setCounts[st] + "→" + after + " 件");
      });
      return notes;
    }
    function finish(containerDrops, stopped) {
      return { blocked: false, drops: drops, setNotes: setNotesNow(),
        containerDrops: containerDrops || [], stopped: !!stopped,
        missing: Object.keys(state.missingSkills), skills: skillDisplayMap(state.skillVals) };
    }

    // 容器（提供 #口袋位）一旦掉落，口袋物品的掉落顺序不可知：
    // 不再推演后续连锁，只返回警告。直接卸下容器本身也按此处理。
    if (isContainer(excludeName)) return finish([excludeName], true);

    for (let guard = 0; guard < 80; guard++) {
      const low = lowAttr(state);
      if (low) {
        const fixer = worstNegativeItem(state, low.attr);
        if (!fixer) {
          return { blocked: true, attr: low.attr, value: low.value, drops: drops, setNotes: setNotesNow(),
            missing: Object.keys(state.missingSkills), skills: skillDisplayMap(state.skillVals) };
        }
        removed.add(fixer);
        drops.push({ name: fixer, reasons: ["属性保护：" + low.attr + " " + fmtNum(low.value) + " < 1，强制卸下"] });
        rebuildState(state, base, removed);
        if (isContainer(fixer)) return finish([fixer], true);
        continue;
      }
      let failed = null;
      state.items.forEach(function (n) {
        if (failed) return;
        const reasons = checkReqs(state.itemInfos[n], state, n);
        if (reasons.length) failed = { name: n, reasons: reasons };
      });
      if (!failed) break;
      removed.add(failed.name);
      drops.push({ name: failed.name, reasons: failed.reasons });
      rebuildState(state, base, removed);
      if (isContainer(failed.name)) return finish([failed.name], true);
    }
    return finish([], false);
  }

  function rebuildState(state, base, removed) {
    state.items = new Set();
    base.items.forEach(function (n) { if (!removed.has(n)) state.items.add(n); });
    state.setCounts = setCountsOf(state.items);
    state.skillVals = computeSkills(state.skillRows || base.skillRows,
      { items: state.items, level: state.level, prof: base.prof }, removed);
  }

  /* ---------------- 界面 ---------------- */
  // 左下角装饰：露帕（Lupa）卡片（装备页专用）。与 SL 明细插件的同名卡片争用同一位置时，以本插件为准。
  // 卡片图：露帕（Lupa），360×526 JPEG 内嵌，固定一张，避免额外网络请求。
  const LUPA_SRC = 'data:image/jpeg;base64,';
  const TAROT_DECK = [{"name":"LUPA","src":LUPA_SRC}];
  // 彩蛋位也用同一张露帕图：不再有随机整蛊图。
  function tarotPick() { return TAROT_DECK[0]; }

  const CSS = `
  .wodt-badge {
    display:inline-block; width:16px; height:16px; line-height:16px; text-align:center;
    border-radius:50%; background:#d9342b; color:#fff; font:bold 12px/16px sans-serif;
    margin-left:4px; cursor:help; vertical-align:middle; box-shadow:0 0 0 1px rgba(0,0,0,.25);
  }
  .wodt-badge.wodt-lock { background:#7a1f1a; }
  .wodt-badge.wodt-loading { background:#999; }
  #wodt-banner {
    position:fixed; right:14px; bottom:14px; z-index:99999; max-width:360px;
    background:#fffdf5; border:1px solid #c9b98d; border-radius:6px; padding:8px 10px;
    font:12px/1.5 "Microsoft YaHei",sans-serif; color:#3b3322;
    box-shadow:0 4px 14px rgba(0,0,0,.18);
  }
  #wodt-banner b { color:#a33; }
  #wodt-tip {
    position:fixed; z-index:100000; max-width:420px; max-height:60vh; overflow:auto; display:none;
    background:#fffdf5; border:1px solid #c9b98d; border-radius:6px; padding:8px 10px;
    font:12px/1.6 "Microsoft YaHei",sans-serif; color:#2f2a1d;
    box-shadow:0 6px 20px rgba(0,0,0,.22);
  }
  /* 游戏皮肤里有全局 ol/ul{color:#FFFFFF}，不显式覆盖会让列表在米色背景上“消失” */
  #wodt-tip h5 { margin:0 0 6px; font-size:12px; color:#a33; }
  .wodt-warn { color:#c62828; font-weight:bold; margin:5px 0; }
  #wodt-tip li.wodt-warnli, #wodt-panel li.wodt-warnli { color:#c62828; font-weight:bold; }
  #wodt-tip ol { margin:0; padding-left:18px; color:#2f2a1d; }
  #wodt-tip li { margin:2px 0; color:#2f2a1d; }
  #wodt-tip b, #wodt-tip .note { color:#2b2416; }
  #wodt-tip .note { margin-top:6px; color:#7a6a4a; }
  #wodt-panel {
    position:fixed; right:14px; top:14px; z-index:100001; width:450px; max-height:80vh; overflow:auto;
    background:#fffdf5; border:1px solid #c9b98d; border-radius:6px;
    font:12px/1.6 "Microsoft YaHei",sans-serif; color:#2f2a1d;
    box-shadow:0 8px 26px rgba(0,0,0,.25); text-align:left;
  }
  #wodt-panel h4 {
    margin:0; padding:7px 10px; font-size:13px; color:#3b3322;
    background:#efe3c8; border-bottom:1px solid #d8c69c;
    display:flex; justify-content:space-between; align-items:center;
  }
  #wodt-panel .wodt-x { cursor:pointer; color:#7a6a4a; padding:0 4px; }
  #wodt-panel .wodt-body { padding:6px 10px 10px; }
  #wodt-panel .wodt-item { border-top:1px dashed #e0d6bb; padding:6px 0; }
  #wodt-panel .wodt-item:first-child { border-top:0; }
  #wodt-panel .wodt-item.focus { background:#fff4e2; }
  #wodt-panel .t { font-weight:bold; color:#a33; }
  #wodt-panel ol { margin:2px 0 2px 18px; padding:0; color:#2f2a1d; }
  #wodt-panel li, #wodt-panel b { color:#2f2a1d; }
  #wodt-panel .n { color:#7a6a4a; margin-top:2px; }
  `;

  function addStyle() {
    if (document.getElementById("wodt-style")) return;
    const st = document.createElement("style");
    st.id = "wodt-style";
    st.textContent = CSS;
    document.head.appendChild(st);
  }


  const DEATH_BOX_ID = "wodt-death";
  const DEATH_STYLE_ID = "wodt-death-style";
  const DEATH_HIDE_KEY = "wodt_death_hidden";
  function addDeathGadget() {
    // 立绘统一由控制面板的「左下角立绘」开关管理，关掉时不插入
    if (!window.__WOD_PET_ENABLED__) return;
    if (document.getElementById(DEATH_BOX_ID)) { watchDeathGadget(); return; }
    // 与 SL 插件同一个挂载点：左侧菜单 gadget 的 body 末尾（搜索框下方）
    const left = document.querySelector("#gadgettable-left-gadgets .gadget.menu .gadget_body") ||
      document.getElementById("gadgettable-left-gadgets") ||
      document.getElementById("gadgettable-left");
    if (!left) return;
    // 冲突：SL 插件会在同一位置放 THE FOOL，这里以本插件为准，先摘掉它
    const rival = document.getElementById("wodsl-fool");
    if (rival && rival.parentNode) rival.parentNode.removeChild(rival);
    if (!document.getElementById(DEATH_STYLE_ID)) {
      const st = document.createElement("style");
      st.id = DEATH_STYLE_ID;
      // 与 SL 插件同一套防溢出口径：border-box 消除 1px 边框造成的 142px 超宽，
      // overflow:clip + contain:paint 把 rotateY 中间帧的透视放大裁在卡片内，避免左栏冒滚动条。
      st.textContent = "#" + DEATH_BOX_ID + "{width:100%;max-width:140px;margin:8px auto 12px;padding:0;line-height:0;cursor:pointer;" +
        "box-sizing:border-box;perspective:900px;overflow:clip;contain:layout paint;}" +
        "#" + DEATH_BOX_ID + " .wodt-card{position:relative;transition:transform .42s ease;transform-style:preserve-3d;" +
        "box-sizing:border-box;}" +
        "#" + DEATH_BOX_ID + ".flipped .wodt-card{transform:rotateY(180deg);}" +
        "#" + DEATH_BOX_ID + " img{display:block;width:100%;height:auto;border:1px solid #6b5a3a;border-radius:2px;" +
        "box-sizing:border-box;box-shadow:0 2px 6px rgba(0,0,0,.45);background:#111;backface-visibility:hidden;}" +
        "#" + DEATH_BOX_ID + " .wodt-back{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;" +
        "border:1px solid #6b5a3a;border-radius:2px;box-sizing:border-box;" +
        "background:radial-gradient(circle at 50% 50%,#2a2418,#14110b);" +
        "color:#c9b27a;font-size:11px;line-height:1.4;text-align:center;padding:0 4px;word-break:break-word;transform:rotateY(180deg);" +
        "backface-visibility:hidden;letter-spacing:.5px;}" +
        "#wodt-death-restore{display:none;width:100%;max-width:140px;margin:8px auto 12px;padding:3px 0;" +
        "border:1px dashed #6b5a3a;border-radius:2px;box-sizing:border-box;background:#14110b;color:#c9b27a;font-size:11px;" +
        "line-height:1.5;text-align:center;cursor:pointer;user-select:none;}" +
        "#wodt-death-restore:hover{background:#241f14;color:#e8d7a6;}";
      (document.head || document.documentElement).appendChild(st);
    }
    const restore = document.createElement("div");
    restore.id = "wodt-death-restore";
    restore.textContent = "🃏 点此显示露帕图";
    restore.title = "显示左下角露帕图";
    left.appendChild(restore);

    const box = document.createElement("div");
    box.id = DEATH_BOX_ID;
    box.title = "点击翻转收起，再次点击显示";
    const card = document.createElement("div");
    card.className = "wodt-card";
    let cur = tarotPick();
    const img = document.createElement("img");
    img.alt = cur.name;
    img.src = cur.src;
    const back = document.createElement("div");
    back.className = "wodt-back";
    back.textContent = cur.name;
    card.appendChild(img);
    card.appendChild(back);
    box.appendChild(card);
    let hiding = null;
    function setHidden(hide, instant) {
      if (hiding) { clearTimeout(hiding); hiding = null; }
      if (hide) {
        box.classList.add("flipped");
        localStorage.setItem(DEATH_HIDE_KEY, "1");
        const fin = function () { box.style.display = "none"; restore.style.display = "block"; };
        if (instant) fin(); else hiding = setTimeout(fin, 440);
      } else {
        // 重新出现时沿用同一张露帕卡片。
        cur = tarotPick();
        img.src = cur.src;
        img.alt = cur.name;
        back.textContent = cur.name;
        box.style.display = "";
        restore.style.display = "none";
        localStorage.setItem(DEATH_HIDE_KEY, "0");
        if (instant) box.classList.remove("flipped");
        else setTimeout(function () { box.classList.remove("flipped"); }, 20);
      }
    }
    box.addEventListener("click", function () { setHidden(true); });
    restore.addEventListener("click", function () { setHidden(false); });
    left.appendChild(box);
    if (localStorage.getItem(DEATH_HIDE_KEY) === "1") setHidden(true, true);
    watchDeathGadget(left);
  }

  // SL 插件可能在之后才插入 THE FOOL，或页面局部重绘把图顶掉：持续校正
  let deathObserver = null;
  function watchDeathGadget(scope) {
    if (deathObserver || !window.MutationObserver) return;
    const target = scope ||
      document.querySelector("#gadgettable-left-gadgets .gadget.menu .gadget_body") ||
      document.body;
    if (!target) return;
    let queued = false;
    deathObserver = new MutationObserver(function () {
      if (queued) return;
      queued = true;
      setTimeout(function () {
        queued = false;
        const rival = document.getElementById("wodsl-fool");
        if (rival && rival.parentNode) rival.parentNode.removeChild(rival);
        const rivalRestore = document.getElementById("wodsl-fool-restore");
        if (rivalRestore && rivalRestore.parentNode) rivalRestore.parentNode.removeChild(rivalRestore);
        if (!document.getElementById(DEATH_BOX_ID)) addDeathGadget();
      }, 0);
    });
    deathObserver.observe(target, { childList: true, subtree: true });
  }

  let bannerEl = null;
  function banner(text) {
    if (!bannerEl) {
      bannerEl = document.createElement("div");
      bannerEl.id = "wodt-banner";
      document.body.appendChild(bannerEl);
    }
    bannerEl.innerHTML = text;
    bannerEl.style.display = "block";
    return bannerEl;
  }
  function hideBanner(delay) {
    setTimeout(function () { if (bannerEl) bannerEl.style.display = "none"; }, delay || 0);
  }

  let tipEl = null;
  function tip() {
    if (!tipEl) {
      tipEl = document.createElement("div");
      tipEl.id = "wodt-tip";
      document.body.appendChild(tipEl);
    }
    return tipEl;
  }
  function showTip(html, x, y) {
    const t = tip();
    t.innerHTML = html;
    t.style.display = "block";
    t.style.maxHeight = Math.max(140, Math.floor(window.innerHeight * 0.6)) + "px";
    const w = t.offsetWidth, h = t.offsetHeight;
    let left = x + 16, top = y + 12;
    if (left + w > window.innerWidth - 8) left = x - w - 12;
    if (top + h > window.innerHeight - 8) top = y - h - 12;
    /* 兜底：让浮层完整落在可视区内，避免只看到标题、列表被截掉 */
    left = Math.max(6, Math.min(left, window.innerWidth - w - 8));
    top = Math.max(6, Math.min(top, window.innerHeight - h - 8));
    t.style.left = left + "px";
    t.style.top = top + "px";
  }
  function hideTip() { if (tipEl) tipEl.style.display = "none"; }

  function isRisky(res) {
    return !!(res && (res.blocked || res.drops.length || (res.containerDrops && res.containerDrops.length)));
  }

  function plainSummary(name, res) {
    if (res.blocked) {
      return "不能卸下「" + name + "」：" + res.attr + " 会降到 " + fmtNum(res.value) + "（<1），会锁死";
    }
    const hasContainer = res.containerDrops && res.containerDrops.length;
    if (hasContainer) {
      const head = "卸下「" + name + "」会导致容器掉落（" + res.containerDrops.join("、") + "），后果不可知";
      return res.drops.length ? head + "；此前已脱落：" +
        res.drops.map(function (d) { return d.name + "（" + d.reasons.join("；") + "）"; }).join("；") : head;
    }
    return "卸下「" + name + "」会连锁脱落 " + res.drops.length + " 件：" +
      res.drops.map(function (d) { return d.name + "（" + d.reasons.join("；") + "）"; }).join("；");
  }

  let detailEl = null;
  function closeDetail() { if (detailEl) { detailEl.remove(); detailEl = null; } }
  function showDetail(gear, results, focusName) {
    closeDetail();
    const seen = {};
    const list = [];
    gear.forEach(function (g) {
      if (seen[g.name]) return;
      seen[g.name] = 1;
      const r = results[g.name];
      if (isRisky(r)) list.push(g);
    });
    if (focusName) {
      list.sort(function (a, b) { return (b.name === focusName) - (a.name === focusName); });
    }
    detailEl = document.createElement("div");
    detailEl.id = "wodt-panel";
    let h = '<h4><span>装备连锁明细（' + list.length + ' 种）</span><span class="wodt-x" title="关闭">✕</span></h4><div class="wodt-body">';
    if (!list.length) h += '<div class="n">没有发现会连锁脱落的装备。</div>';
    list.forEach(function (g) {
      const r = results[g.name];
      h += '<div class="wodt-item' + (g.name === focusName ? ' focus' : '') + '">';
      const hasC = !r.blocked && r.containerDrops && r.containerDrops.length;
      const tail = r.blocked ? "（不能卸下）"
        : (r.drops.length ? "（会掉 " + r.drops.length + " 件" + (hasC ? "，含容器" : "") + "）"
          : "（会导致容器掉落）");
      h += '<div class="t">「' + esc(g.name) + '」' + tail + '</div>';
      if (r.blocked) {
        h += '<div>' + esc(r.attr) + ' 会降到 ' + fmtNum(r.value) + '（&lt;1），且没有可自动脱下的减值装备可修复 → 锁死。</div>';
      } else {
        if (r.containerDrops && r.containerDrops.length) {
          h += '<div class="wodt-warn">⚠ 此行为会导致容器掉落，造成严重的不可知后果</div>';
        }
        h += '<ol>' + r.drops.map(function (d) {
          const isContainer = r.containerDrops && r.containerDrops.indexOf(d.name) >= 0;
          return '<li' + (isContainer ? ' class="wodt-warnli"' : '') + '><b>' + esc(d.name) + '</b>：' + esc(d.reasons.join("；")) + '</li>';
        }).join('') + '</ol>';
      }
      if (r.setNotes && r.setNotes.length) h += '<div class="n">套装降档：' + esc(r.setNotes.join("，")) + '</div>';
      if (r.missing && r.missing.length) h += '<div class="n">技能页没有读到：' + esc(r.missing.join("、")) + "（已跳过）</div>";
      h += '</div>';
    });
    h += '<div class="n">按当前装备与人物数据推算；每件装备的要求已扣除其自身提供的基础加成/减益；临时增益（药水/光环）未计入；同名装备按名字判定。</div></div>';
    detailEl.innerHTML = h;
    document.body.appendChild(detailEl);
    if (focusName) {
      const f = detailEl.querySelector('.wodt-item.focus');
      if (f && f.scrollIntoView) f.scrollIntoView({ block: 'nearest' });
    }
    detailEl.querySelector('.wodt-x').onclick = closeDetail;
    return detailEl;
  }

  function resultHtml(name, res) {
    if (res.blocked) {
      return '<h5>不能卸下「' + esc(name) + '」</h5>' +
        '<div>卸下后 <b>' + esc(res.attr) + '</b> 会降到 <b>' + fmtNum(res.value) +
        " (&lt;1)</b>，且没有可自动脱下的减值装备可修复 → 会触发锁死。</div>";
    }
    const hasContainer = res.containerDrops && res.containerDrops.length;
    if (!res.drops.length && !hasContainer) return "";
    let h = '<h5>卸下「' + esc(name) + '」' +
      (res.drops.length ? '会连锁脱落 ' + res.drops.length + ' 件' : '会导致容器掉落') + '</h5>';
    if (hasContainer) {
      h += '<div class="wodt-warn">⚠ 此行为会导致容器掉落，造成严重的不可知后果</div>';
    }
    if (res.drops.length) {
      h += '<ol>';
      res.drops.forEach(function (d) {
        const isContainer = res.containerDrops && res.containerDrops.indexOf(d.name) >= 0;
        h += '<li' + (isContainer ? ' class="wodt-warnli"' : '') + '><b>' + esc(d.name) + '</b>：' + esc(d.reasons.join("；")) + '</li>';
      });
      h += "</ol>";
    }
    if (hasContainer) {
      h += '<div class="note">容器掉落后口袋物品的掉落顺序不可知，已停止后续计算。</div>';
    }
    if (res.setNotes && res.setNotes.length) {
      h += '<div class="note">套装降档：' + esc(res.setNotes.join("，")) + "</div>";
    }
    if (res.missing && res.missing.length) {
      h += '<div class="note">技能页没有读到：' + esc(res.missing.join("、")) + "（这些要求已跳过，未计入）</div>";
    }
    h += '<div class="note">按当前装备与人物数据推算；每件装备的要求已扣除其自身基础加成/减益；临时增益（药水/光环）未计入。</div>';
    return h;
  }

  function renderBadges(gear, results) {
    gear.forEach(function (g) {
      const res = results[g.name];
      if (!res) return;
      let badge = g.sel.parentNode.querySelector(".wodt-badge[data-for='" + g.slot + "_" + g.idx + "']");
      if (!badge) {
        badge = document.createElement("span");
        badge.className = "wodt-badge";
        badge.dataset.for = g.slot + "_" + g.idx;
        // 口袋行的下拉框很宽（列宽由最长的物品名决定），徽章插在右侧可能被表格右边界裁掉；
        // 口袋里改插在下拉框左侧，保证红色感叹号始终可见。
        if (g.slot === "go_tasche") g.sel.parentNode.insertBefore(badge, g.sel);
        else g.sel.insertAdjacentElement("afterend", badge);
      }
      if (isRisky(res)) {
        badge.textContent = "!";
        badge.classList.toggle("wodt-lock", !!res.blocked);
        badge.style.display = "inline-block";
        badge.onmouseenter = function (ev) { showTip(resultHtml(g.name, res), ev.clientX, ev.clientY); };
        badge.onmousemove = function (ev) { showTip(resultHtml(g.name, res), ev.clientX, ev.clientY); };
        badge.onmouseleave = hideTip;
        badge.onclick = function (ev) { ev.preventDefault(); ev.stopPropagation(); hideTip(); showDetail(gear, results, g.name); };
      } else {
        badge.style.display = "none";
      }
    });
  }

  /* ---------------- 主流程 ---------------- */
  function heroUrl(hid, page) {
    return "/wod/spiel/hero/" + page + ".php?session_hero_id=" + encodeURIComponent(hid);
  }

  function countSkillRows(html) {
    try {
      return collectSkillRows(new DOMParser().parseFromString(html, "text/html")).length;
    } catch (e) { return 0; }
  }

  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  // 技能页偶发返回“跳转页/空页”（会话锁、未选中英雄等），读到 0 条时依次重试：
  // 1) 原地址 + 时间戳；2) 弹窗版（IS_POPUP=1，内容相同但更短）；3) 再等一会重试一次。
  function fetchSkills(hid, attempt) {
    const n = attempt || 0;
    const url = n === 0 ? heroUrl(hid, "skills")
      : n === 1 ? heroUrl(hid, "skills") + "&_=" + Date.now()
        : heroUrl(hid, "skills") + "&IS_POPUP=1&_=" + Date.now();
    return fetchText(url).then(function (html) {
      if (countSkillRows(html) > 0 || n >= 2) return html;
      return sleep(n === 0 ? 400 : 1200).then(function () { return fetchSkills(hid, n + 1); });
    }).catch(function () {
      if (n >= 2) return "";
      return sleep(600).then(function () { return fetchSkills(hid, n + 1); });
    });
  }

  function loadHero(hid) {
    const key = CACHE_HERO + hid;
    const cached = cacheGet(key, HERO_TTL);
    if (cached && cached.attrs && cached.skills) return Promise.resolve(cached);
    return fetchText(heroUrl(hid, "attributes")).then(function (attrsHtml) {
      return fetchSkills(hid, 0).then(function (skillsHtml) {
        const v = { attrs: attrsHtml, skills: skillsHtml };
        // 空技能页不写缓存，避免 5 分钟内一直按 0 计算
        if (countSkillRows(skillsHtml) > 0) cacheSet(key, v);
        return v;
      });
    });
  }

  // 物品页：完整版约 190KB（带整套背包下拉框），弹窗版约 20KB，字段（装备要求/位置/类别/口袋位）完全一致，
  // 46 件串行抓取可从约 2 分钟降到约 30 秒。
  function itemPageLooksValid(html) {
    return /装备要求|装备位置|物品类别/.test(String(html || ""));
  }
  function loadItem(hid, item, attempt) {
    const key = CACHE_ITEM + item.name;
    const cached = cacheGet(key, ITEM_TTL);
    // 旧缓存或解析失败留下的空对象（位置/类别/要求全空）不可信，重新抓
    if (cached && cached.schema === ITEM_SCHEMA && (cached.pos || cached.category || cached.reqText)) return Promise.resolve(cached);
    if (!item.iid || !/^\d+$/.test(item.iid)) {
      return Promise.resolve({ schema: ITEM_SCHEMA, name: item.name, reqs: [], categories: [], pocketBonus: 0, reqText: "", pos: "", category: "" });
    }
    const n = attempt || 0;
    const url = "/wod/spiel/hero/item.php?item_instance_id=" + encodeURIComponent(item.iid) +
      "&type=0&session_hero_id=" + encodeURIComponent(hid) + "&IS_POPUP=1" + (n ? "&_=" + Date.now() : "");
    return fetchText(url).then(function (html) {
      if (!itemPageLooksValid(html)) throw new Error("物品页不完整");
      const info = parseItemPage(html, item.name);
      cacheSet(key, info);
      return info;
    }).catch(function () {
      if (n >= 1) {
        return { schema: ITEM_SCHEMA, name: item.name, reqs: [], categories: [], pocketBonus: 0, reqText: "", pos: "", category: "", failed: true };
      }
      return loadItem(hid, item, n + 1);
    });
  }

  function main() {
    if (!/\/items\.php$/.test(location.pathname)) return;
    if (!/[?&]view=gear\b/.test(location.search)) return;
    const hid = (location.search.match(/session_hero_id=(\d+)/) || [])[1];
    if (!hid) return;
    const gear = parseGear(document);
    if (!gear.length) return;

    addStyle();
    addDeathGadget();
    banner("装备连锁检查：读取人物属性与技能…");

    loadHero(hid).then(function (hero) {
      const attrData = parseAttrs(hero.attrs);
      const sdoc = new DOMParser().parseFromString(hero.skills, "text/html");
      let skillRows = collectSkillRows(sdoc);
      // 兜底：页面上没渲染成行的技能（或整页结构变化）用页面内嵌 JS 数据补齐
      const scriptRows = parseSkillScript(hero.skills);
      const known = {};
      const scriptByName = {};
      scriptRows.forEach(function (r) { scriptByName[skillKey(r.name)] = r; });
      // DOM 行可能因为嵌套表格把“技能名”和“等级单元格”配错；脚本数据按 id 精确对应，
      // 同名时用它校正 base/game（tips 仍保留 DOM 的完整来源列表）。
      skillRows.forEach(function (r) {
        const s = scriptByName[skillKey(r.name)];
        if (s) { r.base = s.base; if (s.game != null) r.game = s.game; }
        known[r.name] = 1;
      });
      scriptRows.forEach(function (r) { if (!known[r.name]) { known[r.name] = 1; skillRows.push(r); } });
      const prof = (attrData.prof || "");
      const pv = sdoc.querySelector('input[name="klasse_name"]');
      const profName = pv ? pv.value : prof;

      const seen = {};
      const uniq = [];
      gear.forEach(function (g) { if (!seen[g.name]) { seen[g.name] = 1; uniq.push(g); } });

      banner("装备连锁检查：读取装备详情 0/" + uniq.length + "…（首次约 30 秒，之后走缓存）");
      let done = 0;
      const infos = {};
      const seq = uniq.reduce(function (p, g) {
        return p.then(function () {
          return loadItem(hid, g).then(function (info) {
            infos[g.name] = info;
            done++;
            banner("装备连锁检查：读取装备详情 " + done + "/" + uniq.length + "…");
          });
        });
      }, Promise.resolve());

      return seq.then(function () {
        const failed = Object.keys(infos).filter(function (n) { return infos[n].failed; });
        const base = buildBase(attrData, skillRows, gear, infos, profName);
        base.skillRows = skillRows;
        base.prof = profName;
        const skillCount = Object.keys(base.skillVals).length;
        banner("装备连锁检查：模拟中…（技能页 " + skillCount + " 条技能）" +
          (failed.length ? "（" + failed.length + " 件装备详情读取失败，未纳入）" : ""));
        const results = {};
        gear.forEach(function (g) {
          if (!results[g.name]) results[g.name] = simulate(base, g.name);
        });
        renderBadges(gear, results);

        const missingSet = {};
        Object.keys(results).forEach(function (n) {
          (results[n].missing || []).forEach(function (k) { missingSet[k] = 1; });
        });
        const missing = Object.keys(missingSet);

        const risky = Object.keys(results).filter(function (n) { return isRisky(results[n]); });
        const clear = ' <a href="#" id="wodt-clear" style="color:#7a6a4a;">清空缓存重读</a>';
        const warn = missing.length
          ? '<div style="color:#8a5a00;">技能页未找到：' + esc(missing.join("、")) + "（这些技能要求已跳过）</div>"
          : (skillCount === 0 ? '<div style="color:#8a5a00;">技能页没有读到技能，技能类要求已全部跳过</div>' : "");
        if (risky.length) {
          const preview = risky.slice(0, 3).join("、") + (risky.length > 3 ? " 等" : "");
          banner("装备连锁检查完成：<b>" + risky.length + "</b> 种装备卸下会导致连锁脱落（红色 !）：" + esc(preview) + "。" +
            ' <a href="#" id="wodt-detail" style="color:#21527d;">查看明细</a>' + clear + warn);
          hideBanner(missing.length ? 60000 : 20000);
        } else {
          banner("装备连锁检查完成：没有发现会连锁脱落的装备（技能页 " + skillCount + " 条）。" + clear + warn);
          hideBanner(missing.length ? 60000 : 8000);
        }
        const dl = document.getElementById("wodt-detail");
        if (dl) dl.onclick = function (e) {
          e.preventDefault();
          showDetail(gear, results, null);
        };
        const cl = document.getElementById("wodt-clear");
        if (cl) cl.onclick = function (e) {
          e.preventDefault();
          Object.keys(localStorage).forEach(function (k) {
            if (k.indexOf("wodcg_item_") === 0 || k.indexOf("wodcg_hero_") === 0) localStorage.removeItem(k);
          });
          location.reload();
        };
      });
    }).catch(function (e) {
      console.error("[WoD 装备连锁]", e);
      banner("<b>装备连锁检查失败：</b>" + esc(e && e.message ? e.message : e));
      hideBanner(12000);
    });
  }

