/** 立绘挂在 body 上，用 position:fixed 定位到视口左上角，可拖动 */
function wodPetHost() {
  return document.body || document.documentElement;
}

let wodPetCleanup = null;

/**
 * 立绘只在「带左侧栏的完整界面」显示。
 * 物品详情等 wo() 弹出的小窗口没有左右侧栏、宽度很窄，固定定位的卡片会
 * 直接压在物品名上，所以这类页面一律不挂。
 */
function wodPetAllowedHere() {
  const w = window.innerWidth || document.documentElement.clientWidth || 0;
  if (w && w < 520) return false;                       // 太窄，放不下
  const left = document.getElementById("gadgettable-left");
  if (!left) return false;                              // 没有左侧栏 = 弹窗/精简布局
  try {
    if (window.getComputedStyle(left).display === "none") return false;
  } catch (e) {}
  // 物品详情弹窗即使带侧栏，窗口一般也不宽，这里再兜一层
  if (/[?&]IS_POPUP=1/i.test(location.search) && w && w < 900) return false;
  return true;
}

/** 按当前配置渲染立绘；坐标记在 WOD_PET_POS，默认贴视口左上角 */
function renderLeftPet() {
  if (!window.__WOD_PET_ENABLED__) return;
  if (!wodPetAllowedHere()) {
    // 弹窗/窄布局里不显示，顺便清掉可能残留的旧节点
    const old = document.getElementById("wodPetBox");
    if (old && old.parentNode) old.parentNode.removeChild(old);
    const oldR = document.getElementById("wodPetRestore");
    if (oldR && oldR.parentNode) oldR.parentNode.removeChild(oldR);
    return;
  }

  if (wodPetCleanup) {
    wodPetCleanup();
    wodPetCleanup = null;
  }

  const stale = document.getElementById("wodPetBox");
  if (stale && stale.parentNode) stale.parentNode.removeChild(stale);
  const staleR = document.getElementById("wodPetRestore");
  if (staleR && staleR.parentNode) staleR.parentNode.removeChild(staleR);

  const list = wodPetLoad();
  const total = list.length || 1;
  if (wodPetIdx < 0 || wodPetIdx >= total) {
    wodPetIdx = Math.floor(Math.random() * total);
  }

  wodPetStyle();

  const box = document.createElement("div");
  box.id = "wodPetBox";
  const card = document.createElement("div");
  card.className = "wodpet-card";
  const img = document.createElement("img");
  const back = document.createElement("div");
  back.className = "wodpet-back";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "wodpet-close";
  close.textContent = "×";
  close.title = "收起立绘";
  card.appendChild(img);
  card.appendChild(back);
  box.appendChild(card);
  box.appendChild(close);

  const restore = document.createElement("div");
  restore.id = "wodPetRestore";
  restore.textContent = "🃏 点此显示立绘";
  restore.title = "重新显示左下角立绘";

  function paint() {
    const cur = list.length
      ? list[wodPetIdx % list.length]
      : { name: "露帕", src: window.__WOD_LUPA_SRC__ || "" };
    if (!cur || !cur.src) {
      box.style.display = "none";
      return;
    }
    img.src = cur.src;
    img.alt = cur.name || "";
    back.textContent = cur.name || "";
    box.title =
      (cur.name || "立绘") +
      (list.length > 1 ? "（点击切换下一张）" : "（点击翻面）");
  }
  paint();

  /* ---- 位置：默认视口左上角，拖过就记住 ---- */
  const pos = { left: 8, top: 8 };
  try {
    const saved = JSON.parse(localStorage.getItem(WOD_PET_POS_KEY) || "null");
    if (saved && isFinite(saved.left) && isFinite(saved.top)) {
      pos.left = saved.left;
      pos.top = saved.top;
    }
  } catch (e) {}

  function place(l, t) {
    const vw = window.innerWidth || document.documentElement.clientWidth || 800;
    const vh = window.innerHeight || document.documentElement.clientHeight || 600;
    const bw = box.offsetWidth || 140;
    const bh = box.offsetHeight || 0;
    const maxLeft = Math.max(0, vw - bw);
    const maxTop = Math.max(0, vh - Math.min(bh, 60)); // 至少留 60px 在视口内
    pos.left = Math.min(Math.max(0, Math.round(l)), maxLeft);
    pos.top = Math.min(Math.max(0, Math.round(t)), maxTop);
    box.style.left = pos.left + "px";
    box.style.top = pos.top + "px";
    restore.style.left = pos.left + "px";
    restore.style.top = pos.top + "px";
  }

  /* ---- 拖动（鼠标 + 触摸），拖动后不再触发换图 ---- */
  let drag = null;
  let suppressClick = false;

  function savePos() {
    try {
      localStorage.setItem(WOD_PET_POS_KEY, JSON.stringify(pos));
    } catch (e) {}
  }
  function onMove(e) {
    if (!drag) return;
    const dx = e.clientX - drag.x;
    const dy = e.clientY - drag.y;
    if (!drag.moved && Math.abs(dx) + Math.abs(dy) < 4) return;
    drag.moved = true;
    place(drag.left + dx, drag.top + dy);
    if (e.cancelable) e.preventDefault();
  }
  function onUp() {
    if (!drag) return;
    const moved = drag.moved;
    drag = null;
    document.removeEventListener("mousemove", onMove);
    document.removeEventListener("mouseup", onUp);
    if (moved) {
      suppressClick = true;
      savePos();
    }
  }
  card.addEventListener("mousedown", function (e) {
    if (e.button !== 0 || e.target === close) return;
    drag = { x: e.clientX, y: e.clientY, left: pos.left, top: pos.top, moved: false };
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
  });
  card.addEventListener(
    "touchstart",
    function (e) {
      const t = e.touches && e.touches[0];
      if (!t) return;
      drag = { x: t.clientX, y: t.clientY, left: pos.left, top: pos.top, moved: false };
    },
    { passive: true }
  );
  card.addEventListener(
    "touchmove",
    function (e) {
      const t = e.touches && e.touches[0];
      if (!drag || !t) return;
      const dx = t.clientX - drag.x;
      const dy = t.clientY - drag.y;
      if (!drag.moved && Math.abs(dx) + Math.abs(dy) < 6) return;
      drag.moved = true;
      place(drag.left + dx, drag.top + dy);
      if (e.cancelable) e.preventDefault();
    },
    { passive: false }
  );
  card.addEventListener("touchend", function () {
    if (!drag) return;
    const moved = drag.moved;
    drag = null;
    if (moved) {
      suppressClick = true;
      savePos();
    }
  });

  card.onclick = function () {
    if (suppressClick) {
      suppressClick = false;
      return;
    }
    if (list.length <= 1) {
      card.classList.toggle("flipped");
      return;
    }
    card.classList.add("flipped");
    setTimeout(function () {
      wodPetIdx = (wodPetIdx + 1) % list.length;
      paint();
      card.classList.remove("flipped");
    }, 210);
  };

  close.onclick = function (e) {
    e.stopPropagation();
    box.style.display = "none";
    restore.style.display = "block";
    try {
      localStorage.setItem(WOD_PET_HIDDEN_KEY, "1");
    } catch (err) {}
  };
  restore.onclick = function () {
    box.style.display = "";
    restore.style.display = "none";
    try {
      localStorage.setItem(WOD_PET_HIDDEN_KEY, "0");
    } catch (err) {}
  };

  const host = wodPetHost();
  host.appendChild(box);
  host.appendChild(restore);
  place(pos.left, pos.top);

  // 图片加载后高度变化，重新夹一次，别让卡片跑到视口外
  img.addEventListener("load", function () {
    place(pos.left, pos.top);
  });

  function onResize() {
    if (!document.body || !document.body.contains(box)) return;
    if (!wodPetAllowedHere()) {
      // 拖窄到弹窗宽度或侧栏消失时先收起来
      box.style.display = "none";
      restore.style.display = "none";
      return;
    }
    if (localStorage.getItem(WOD_PET_HIDDEN_KEY) === "1") {
      box.style.display = "none";
      restore.style.display = "block";
    } else {
      box.style.display = "";
      restore.style.display = "none";
    }
    place(pos.left, pos.top);
  }
  window.addEventListener("resize", onResize);
  wodPetCleanup = function () {
    window.removeEventListener("resize", onResize);
  };

  if (localStorage.getItem(WOD_PET_HIDDEN_KEY) === "1") {
    box.style.display = "none";
    restore.style.display = "block";
  }
}

/** 控制面板里的图片管理区（无论开关是否打开都可编辑） */
function initLeftPetManager() {
  if (typeof $ === "undefined" || !$panelBody || !$panelBody.length) return;
  if (document.getElementById("wodPetMgr")) return;

  const $box = $(`
    <div id="wodPetMgr" style="margin-top:6px;border-top:1px solid #888;padding-top:4px;font-size:11px;">
      <div style="font-weight:bold;">立绘图片管理</div>
      <div style="display:flex;align-items:center;gap:2px;margin-top:2px;">
        <input type="text" class="wodpet-url" placeholder="图片网址" style="width:78px;font-size:11px;padding:1px;">
        <button type="button" class="button clickable wodpet-addurl" style="padding:0 4px;">加</button>
      </div>
      <div style="margin-top:2px;"><input type="file" class="wodpet-file" accept="image/*" multiple style="width:130px;font-size:10px;"></div>
      <div class="wodpet-count" style="color:#999;margin-top:1px;"></div>
      <div class="wodpet-list"></div>
    </div>`);
  $panelBody.append($box);

  function refreshPet() {
    if (loadConfig().leftPet) renderLeftPet();
  }

  function repaint() {
    const list = wodPetLoad();
    $box
      .find(".wodpet-count")
      .text(
        list.length
          ? "共 " + list.length + " 张，点图片切换"
          : "暂无自定义图，显示内置露帕"
      );
    const $list = $box.find(".wodpet-list").empty();
    list.forEach(function (it, i) {
      const $row = $('<div class="wodpet-row"></div>');
      $("<img>")
        .attr("src", it.src)
        .attr("alt", it.name || "")
        .appendTo($row);
      $('<span class="nm"></span>')
        .text(it.name || "未命名")
        .attr("title", it.name || "")
        .appendTo($row);
      $('<button type="button" title="上移">↑</button>')
        .on("click", function () {
          wodPetMove(i, -1, function () {
            repaint();
            refreshPet();
          });
        })
        .appendTo($row);
      $('<button type="button" title="下移">↓</button>')
        .on("click", function () {
          wodPetMove(i, 1, function () {
            repaint();
            refreshPet();
          });
        })
        .appendTo($row);
      $('<button type="button" title="删除">×</button>')
        .on("click", function () {
          if (!confirm("删除立绘「" + (it.name || "未命名") + "」？")) return;
          const left = wodPetLoad().filter(function (p) {
            return p.id !== it.id;
          });
          if (wodPetSave(left)) {
            repaint();
            refreshPet();
          }
        })
        .appendTo($row);
      $list.append($row);
    });
  }

  $box.find(".wodpet-addurl").on("click", function () {
    const $in = $box.find(".wodpet-url");
    const url = String($in.val() || "").trim();
    if (!/^(https?:\/\/|data:image\/)/i.test(url)) {
      alert("请填写 http(s):// 或 data:image/ 开头的图片地址");
      return;
    }
    let name = "网络图";
    try {
      name = decodeURIComponent(url.split("?")[0].split("/").pop() || "网络图").slice(0, 18);
    } catch (e) {}
    wodPetAdd(url, name, function () {
      $in.val("");
      repaint();
      refreshPet();
    });
  });

  $box.find(".wodpet-file").on("change", function () {
    const input = this;
    const files = Array.prototype.slice.call(input.files || []);
    if (!files.length) return;
    const have = wodPetLoad().length;
    if (have + files.length > WOD_PET_MAX) {
      alert("立绘图最多 " + WOD_PET_MAX + " 张，当前已有 " + have + " 张");
      input.value = "";
      return;
    }
    let pending = files.length;
    files.forEach(function (f) {
      wodPetCompress(f, function (src) {
        if (src) {
          const nm = String(f.name || "本地图")
            .replace(/\.[^.]+$/, "")
            .slice(0, 18);
          wodPetAdd(src, nm, null);
        }
        if (--pending === 0) {
          input.value = "";
          repaint();
          refreshPet();
        }
      });
    });
  });

  repaint();
}

